package com.eljefe.interviews;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.content.ContentValues;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.widget.*;import java.io.*;import java.util.*;import java.text.SimpleDateFormat;
public class MainActivity extends Activity{
 int pink=0xffff1493,bg=0xff05050a,white=0xffffffff;LinearLayout list;MediaRecorder rec;File current;ArrayList<String> qs=new ArrayList<>();String mode="";Uri selectedAudio;Uri videoUri;
 public void onCreate(Bundle b){super.onCreate(b);qs.add("¿Cómo valoras la temporada?");qs.add("¿Qué objetivos tiene el equipo?");qs.add("¿Qué mensaje mandas a la afición?");home();}
 TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(white);t.setGravity(Gravity.CENTER);t.setPadding(8,10,8,10);return t;}
 GradientDrawable shape(){GradientDrawable d=new GradientDrawable();d.setColor(0xff151520);d.setCornerRadius(22);d.setStroke(3,pink);return d;}
 void init(String title){LinearLayout root=new LinearLayout(this);root.setPadding(12,12,12,12);root.setOrientation(1);root.setBackgroundColor(bg);ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);root.addView(sc);setContentView(root);TextView h=txt(title,24);h.setTextColor(pink);h.setTypeface(null,1);list.addView(h);}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(white);b.setTextSize(15);b.setAllCaps(false);b.setBackground(shape());b.setOnClickListener(v->r.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);list.addView(b,p);}
 void msg(String s){new AlertDialog.Builder(this).setTitle("EL JEFE 5.0").setMessage(s).setPositiveButton("Aceptar",null).show();}
 void home(){init("👑 EL JEFE 5.0\nENTREVISTAS FÚTBOL");list.addView(txt("C.D. SANTA ANA DE CABAÑAS RARAS",14));btn("🎙 GRABAR ENTREVISTA EN VÍDEO",()->video());btn("🎧 INICIAR GRABACIÓN DE AUDIO",()->startAudio());btn("⏹ DETENER Y GUARDAR AUDIO",()->stopAudio());btn("✂ RECORTAR AUDIO",()->pick("trim"));btn("🔊 MEJORAR VOZ Y REDUCIR RUIDO",()->pick("noise"));btn("〰 SUAVIZAR LA VOZ",()->pick("smooth"));btn("📋 PREGUNTAS PREPARADAS",()->questions());btn("📁 ARCHIVO DE ENTREVISTAS",()->archive());btn("⚙ AJUSTES",()->settings());}
 void video(){try{ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"ELJEFE_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.getDefault()).format(new Date())+".mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.Video.Media.RELATIVE_PATH,Environment.DIRECTORY_MOVIES+"/EL JEFE 5.0");videoUri=getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);Intent i=new Intent(MediaStore.ACTION_VIDEO_CAPTURE);i.putExtra(MediaStore.EXTRA_VIDEO_QUALITY,1);i.putExtra(MediaStore.EXTRA_DURATION_LIMIT,1800);if(videoUri!=null)i.putExtra(MediaStore.EXTRA_OUTPUT,videoUri);if(i.resolveActivity(getPackageManager())==null){if(videoUri!=null)getContentResolver().delete(videoUri,null,null);videoUri=null;msg("No encuentro una app de cámara compatible. Comprueba que la Cámara de Samsung funciona.");return;}startActivityForResult(i,50);}catch(Exception e){msg("No se pudo abrir la cámara. Comprueba los permisos de Cámara en Ajustes del Samsung.");}}
 void startAudio(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},70);return;}try{File dir=getExternalFilesDir(Environment.DIRECTORY_MUSIC);if(!dir.exists())dir.mkdirs();current=new File(dir,"Entrevista_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.getDefault()).format(new Date())+".m4a");rec=new MediaRecorder();rec.setAudioSource(MediaRecorder.AudioSource.VOICE_RECOGNITION);rec.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);rec.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);rec.setOutputFile(current.getAbsolutePath());rec.prepare();rec.start();msg("Grabación iniciada. Se usa la fuente de audio de reconocimiento de voz para aprovechar el procesamiento que admita el teléfono. Pulsa detener cuando termines.");}catch(Exception e){msg("No se pudo iniciar la grabación. Comprueba el permiso del micrófono.");}}
 void stopAudio(){if(rec==null){msg("No hay grabación en curso.");return;}try{rec.stop();rec.release();rec=null;msg("Audio guardado: "+current.getName());}catch(Exception e){msg("No se pudo guardar; prueba a grabar durante más tiempo.");try{rec.release();}catch(Exception x){}rec=null;}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==70&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startAudio();}
 void pick(String m){mode=m;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("audio/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,60);}catch(Exception e){msg("No se pudo abrir el selector de audio.");}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;if(r==50){Uri u=d.getData()!=null?d.getData():videoUri;if(u!=null)msg("Vídeo guardado en la galería, en la carpeta EL JEFE 5.0 si la cámara respetó el destino.");else msg("La cámara no devolvió el vídeo. Comprueba el almacenamiento y vuelve a intentarlo.");videoUri=null;}if(r==60&&d.getData()!=null){selectedAudio=d.getData();if(mode.equals("trim"))trimDialog();else if(mode.equals("noise"))msg("La reducción de ruido se aplica durante nuevas grabaciones cuando el Samsung ofrece ese efecto. El procesamiento avanzado de archivos ya grabados aún no está disponible; no se ha alterado el original.");else if(mode.equals("smooth"))msg("El suavizado de voz de archivos ya grabados aún no está disponible. Para mejorar la voz, graba con el micrófono cerca y activa reducción de ruido en el Samsung.");}}
 void trimDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(20,4,20,4);EditText start=new EditText(this);start.setHint("Inicio en segundos (ej. 0)");start.setInputType(2);EditText end=new EditText(this);end.setHint("Final en segundos (ej. 30)");end.setInputType(2);box.addView(start);box.addView(end);new AlertDialog.Builder(this).setTitle("Recortar audio").setMessage("Introduce el inicio y el final en segundos. Se guardará una copia recortada.") .setView(box).setPositiveButton("Recortar",(di,w)->{try{long a=Long.parseLong(start.getText().toString()),b=Long.parseLong(end.getText().toString());if(a<0||b<=a){msg("El segundo final debe ser mayor que el inicial.");return;}new Thread(()->doTrim(selectedAudio,a,b)).start();}catch(Exception e){msg("Escribe el inicio y final en segundos.");}}).setNegativeButton("Cancelar",null).show();}
 void doTrim(Uri uri,long startSec,long endSec){MediaExtractor ex=new MediaExtractor();MediaMuxer mux=null;try{ex.setDataSource(this,uri,null);int track=-1;for(int i=0;i<ex.getTrackCount();i++){String m=ex.getTrackFormat(i).getString(MediaFormat.KEY_MIME);if(m!=null&&m.startsWith("audio/")){track=i;break;}}if(track<0)throw new Exception("No se encontró una pista de audio.");ex.selectTrack(track);MediaFormat fmt=ex.getTrackFormat(track);File dir=getExternalFilesDir(Environment.DIRECTORY_MUSIC);if(!dir.exists())dir.mkdirs();File out=new File(dir,"Recorte_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.getDefault()).format(new Date())+".m4a");mux=new MediaMuxer(out.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);int dst=mux.addTrack(fmt);mux.start();ex.seekTo(startSec*1000000L,MediaExtractor.SEEK_TO_CLOSEST_SYNC);int cap=1024*1024;java.nio.ByteBuffer buf=java.nio.ByteBuffer.allocate(cap);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){buf.clear();int n=ex.readSampleData(buf,0);if(n<0)break;long t=ex.getSampleTime();if(t>endSec*1000000L)break;if(t>=startSec*1000000L){info.offset=0;info.size=n;info.presentationTimeUs=t-startSec*1000000L;info.flags=ex.getSampleFlags();mux.writeSampleData(dst,buf,info);}ex.advance();}mux.stop();mux.release();mux=null;ex.release();runOnUiThread(()->msg("Recorte guardado: "+out.getName()+"\nPuedes encontrarlo en Archivo de entrevistas."));}catch(Exception e){try{if(mux!=null){mux.stop();mux.release();}}catch(Exception ignored){}try{ex.release();}catch(Exception ignored){}runOnUiThread(()->msg("No se pudo recortar este formato de audio. Prueba con un archivo M4A o AAC."));}}
 void archive(){init("📁 ARCHIVO DE ENTREVISTAS");File dir=getExternalFilesDir(Environment.DIRECTORY_MUSIC);File[] fs=dir==null?null:dir.listFiles();btn("🎙 INICIAR GRABACIÓN",()->startAudio());btn("⏹ DETENER GRABACIÓN",()->stopAudio());if(fs!=null)for(File f:fs)if(f.isFile()){btn("▶ "+f.getName(),()->{try{Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.fromFile(f),"audio/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception e){msg("No se pudo reproducir.");}});}btn("VOLVER",()->home());}
 void questions(){init("📋 PREGUNTAS PREPARADAS");for(String q:qs)list.addView(txt("• "+q,17));btn("＋ AÑADIR PREGUNTA",()->{EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("Nueva pregunta").setView(e).setPositiveButton("Guardar",(d,w)->{if(e.length()>0)qs.add(e.getText().toString());questions();}).setNegativeButton("Cancelar",null).show();});btn("VOLVER",()->home());}
 void settings(){init("⚙ AJUSTES");list.addView(txt("EL JEFE 5.0 · C.D. Santa Ana\nDiseño negro y fucsia",17));btn("VOLVER",()->home());}
}